// Base64-encoded opaque cursor: { created_at: "2026-10-03T12:00:00Z", id: 98124 }
export async function fetchCursorPage(cursorToken?: string, limit = 20) {
  let query = `
    SELECT id, title, created_at
    FROM posts
  `;
  const params: any[] = [];

  if (cursorToken) {
    const { createdAt, id } = decodeCursor(cursorToken);
    // Composite comparison seeks directly via (created_at, id) composite index
    query += ` WHERE (created_at, id) < ($1, $2)`;
    params.push(createdAt, id);
  }

  query += ` ORDER BY created_at DESC, id DESC LIMIT $${params.length + 1}`;
  params.push(limit + 1); // Fetch 1 extra to determine if next page exists

  const rows = await db.query(query, params);
  const hasMore = rows.length > limit;
  const items = hasMore ? rows.slice(0, limit) : rows;
  const nextCursor = hasMore ? encodeCursor(items[items.length - 1]) : null;

  return { items, nextCursor };
}
